<script setup lang="ts">
import{computed,ref}from'vue';import{t}from'../i18n';import NumberInput from'../components/NumberInput.vue';import{weightConversion}from'../logic/materialCalculators'
const sampleAmount=ref<number|null>(null),sampleWeight=ref<number|null>(null),totalWeight=ref<number|null>(null),formulaOpen=ref(false)
const result=computed(()=>weightConversion(sampleAmount.value??NaN,sampleWeight.value??NaN,totalWeight.value??NaN))
function reset(){sampleAmount.value=sampleWeight.value=totalWeight.value=null}
</script>
<template><div class="page business-page material-page"><header class="page-intro"><h1>{{t('materialWeight.title')}}</h1><p>{{t('materialWeight.intro')}}</p></header><div class="business-layout"><section class="panel input-panel"><h2><span>01</span>{{t('common.input')}}</h2><div class="fields-grid single-column"><NumberInput v-model="sampleAmount" :label="t('materialWeight.sampleAmount')" :hint="t('materialWeight.sampleAmountHint')" :unit="t('materialWeight.amountUnit')"/><NumberInput v-model="sampleWeight" :label="t('materialWeight.sampleWeight')" hint="" :unit="t('materialWeight.grams')"/><NumberInput v-model="totalWeight" :label="t('materialWeight.totalWeight')" hint="" :unit="t('materialWeight.grams')"/></div></section><section class="panel business-result"><h2><span>02</span>{{t('common.result')}}</h2><div v-if="result!==null" class="business-primary"><small>{{t('materialWeight.converted')}}</small><strong>{{result.toFixed(2)}} <i>{{t('materialWeight.amountUnit')}}</i></strong></div><p v-else class="business-waiting">{{t('common.waiting')}}</p><button class="business-reset" @click="reset">{{t('common.reset')}}</button></section></div><details class="business-support" :open="formulaOpen" @toggle="formulaOpen=($event.target as HTMLDetailsElement).open"><summary>{{t('common.formula')}}</summary><div><code>{{t('materialWeight.formula')}}</code><p>{{t('materialWeight.formulaNote')}}</p></div></details></div></template>
